package com.example.urlshortener.orchestration.dto; import com.example.urlshortener.orchestration.domain.*; import java.time.Instant; import java.util.UUID; public record WorkflowResponse(UUID id,WorkflowStatus status,WorkflowNode currentNode,String scenario,String policyVersion,String requirement,Instant updatedAt,int retryCount,int version,WorkflowNode resumeNode) { public static WorkflowResponse of(WorkflowRun w){return new WorkflowResponse(w.getId(),w.getStatus(),w.getCurrentNode(),w.getScenario(),w.getPolicyVersion(),w.getRequirement(),w.getUpdatedAt(),w.getRetryCount(),w.getVersion(),w.getResumeNode());}}
